<!doctype html><html><head><meta charset="utf-8"><title>Prescription {{ $prescription->prescription_number }}</title><style>body{font-family:Arial;margin:2rem} @media print{.no-print{display:none}}</style></head><body>
<button class="no-print" onclick="window.print()">Print prescription</button><h1>Prescription</h1><p><strong>No:</strong> {{ $prescription->prescription_number }}</p><p><strong>Patient:</strong> {{ $prescription->patient?->name ?: $prescription->patient_name }}</p><p><strong>Doctor:</strong> {{ $prescription->doctor?->name ?: $prescription->doctor_name }}</p><p><strong>Date:</strong> {{ $prescription->prescription_date?->format('d M Y') }}</p><h3>Medicines</h3><pre>{{ json_encode($prescription->medicines ?: [], JSON_PRETTY_PRINT) }}</pre></body></html>
